package cl.nexbyte.siger.institucional.formulario;
import cl.nexbyte.siger.institucional.documental.*;import cl.nexbyte.siger.institucional.robustez.*;import cl.nexbyte.siger.institucional.nucleo.ContratosNucleo.*;
import java.nio.file.*;import java.io.*;import java.util.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.io.TempDir;import static org.junit.jupiter.api.Assertions.*;
class DocumentalInstitucionalTest {
 @TempDir Path dir;DatosDocumentalesTest x;
 @BeforeEach void abrir()throws Exception{x=new DatosDocumentalesTest(dir);}
 @AfterEach void cerrar()throws Exception{x.close();}
 private cl.nexbyte.siger.institucional.nucleo.CatalogoLaboratorio.Operador prof(){return x.d.catalog.operador("demo.profesional.upr.a");}
 private DocumentosGestion.Documento cargar(UUID key){return x.gestion.cargar(prof(),key,x.uno,x.actuacion,"sintetico.pdf",new ByteArrayInputStream(x.contenido));}
 private int count(String table){return x.d.db.sql.queryForObject("SELECT COUNT(*) FROM "+table,Integer.class);}
 @Test void autorOrigenFechaShaYRecepcionPermanecenSeparados(){var before=x.d.db.sql.queryForList("SELECT body,receipt FROM institutional_inbox ORDER BY id");var doc=cargar(UUID.randomUUID());assertEquals("GESTION_INSTITUCIONAL",doc.origen());assertEquals(prof().id(),doc.autor());assertEquals(x.d.now,doc.fecha());assertEquals(x.contenido.length,doc.tamanio());assertEquals(3,count("communication_registry"));assertEquals(before,x.d.db.sql.queryForList("SELECT body,receipt FROM institutional_inbox ORDER BY id"));assertEquals(1,count("management_document_link"));assertEquals(1,count("document_command"));}
 @Test void reintentoMantieneDocumentoYClaveDistintaDeContenidoConflicta(){var key=UUID.randomUUID();var a=cargar(key);var b=cargar(key);assertEquals(a,b);assertEquals(1,count("institution_document"));assertEquals(1,x.escaneos.get());assertEquals(409,assertThrows(FalloTecnico.class,()->x.gestion.cargar(prof(),key,x.uno,x.actuacion,"sintetico.pdf",new ByteArrayInputStream(new byte[]{9}))).status);}
 @Test void referenciaDosCasosYActuacionConservaUnSoloOriginal()throws Exception{var doc=cargar(UUID.randomUUID());var head=x.d.catalog.operador("demo.jefatura.upr.a");x.gestion.vincular(head,UUID.randomUUID(),doc.id(),x.uno,x.dos,null);assertEquals(2,count("management_document_link"));assertEquals(1,count("institution_document"));try(var physical=Files.list(dir.resolve("archivo/objects/gestion"))){assertEquals(1,physical.count());}var other=x.d.catalog.operador("demo.profesional2.upr.a");assertEquals(doc.sha256(),x.gestion.documento(other,x.dos,doc.id()).sha256());assertEquals(x.dos,x.gestion.documento(other,x.dos,doc.id()).contextos().getFirst().caso());assertEquals(404,assertThrows(FalloTecnico.class,()->x.gestion.documento(prof(),x.dos,doc.id())).status);}
 @Test void otraUnidadNoLeeNiVinculaAunqueConozcaUuid(){var doc=cargar(UUID.randomUUID());assertEquals(404,assertThrows(FalloTecnico.class,()->x.gestion.referencia(x.d.catalog.operador("demo.profesional.upd.a"),x.uno,doc.id())).status);assertEquals(404,assertThrows(FalloTecnico.class,()->x.gestion.vincular(prof(),UUID.randomUUID(),doc.id(),x.uno,x.otra,null)).status);}
 @Test void actuacionDeOtroCasoNoAdmiteDocumento(){assertEquals(404,assertThrows(FalloTecnico.class,()->x.gestion.cargar(x.d.catalog.operador("demo.jefatura.upr.a"),UUID.randomUUID(),x.dos,x.actuacion,"sintetico.pdf",new ByteArrayInputStream(x.contenido))).status);assertEquals(0,count("institution_document"));assertEquals(0,x.escaneos.get());}
 @Test void infeccionExtensionFalsaYScannerCaidoNoPublican(){x.infectado=true;assertEquals(422,assertThrows(FalloTecnico.class,()->cargar(UUID.randomUUID())).status);x.infectado=false;x.formatoInvalido=true;assertEquals(422,assertThrows(FalloTecnico.class,()->cargar(UUID.randomUUID())).status);x.formatoInvalido=false;x.noDisponible=true;assertEquals(503,assertThrows(FalloTecnico.class,()->cargar(UUID.randomUUID())).status);assertEquals(0,count("institution_document"));assertEquals(0,count("document_command"));assertEquals(3,count("document_event"));}
 @Test void falloSqlTrasFsyncConservaOriginalParaReintento(){var key=UUID.randomUUID();x.d.ddl("ALTER TABLE management_document_link ADD CONSTRAINT test_block_link CHECK(context_id='IMPOSIBLE')");try{assertThrows(RuntimeException.class,()->cargar(key));assertEquals(0,count("institution_document"));assertEquals(0,count("document_command"));}finally{x.d.ddl("ALTER TABLE management_document_link DROP "+(System.getenv("ROBUST_DB_URL")==null?"CONSTRAINT":"CHECK")+" test_block_link");}var doc=cargar(key);assertEquals(1,count("institution_document"));assertNotNull(x.gestion.verificarArchivo(x.gestion.referencia(prof(),x.uno,doc.id())));}
 @Test void falloFilesystemNoGeneraMetadatos()throws Exception{Files.writeString(dir.resolve("archivo/objects/gestion"),"bloqueo controlado");assertEquals(503,assertThrows(FalloTecnico.class,()->cargar(UUID.randomUUID())).status);assertEquals(0,count("institution_document"));assertEquals(0,count("document_command"));}
 @Test void multipaginaCacheYZoomNoTransformanOriginalNiDuplicanPaginas(){var doc=cargar(UUID.randomUUID());var ref=x.gestion.referencia(prof(),x.uno,doc.id());assertEquals(3,x.visor.vista(ref).paginas());var first=x.visor.pagina(ref,1);var second=x.visor.pagina(ref,2);assertNotEquals(first.sha256(),second.sha256());assertEquals(first,x.visor.pagina(ref,1));assertEquals(2,x.renders.get());assertEquals(2,count("document_page"));assertEquals(404,assertThrows(FalloTecnico.class,()->x.visor.pagina(ref,4)).status);assertNotNull(x.gestion.verificarArchivo(ref));}
 @Test void originalYDerivadaCorruptosNuncaSeSirven()throws Exception{var doc=cargar(UUID.randomUUID());var ref=x.gestion.referencia(prof(),x.uno,doc.id());var page=x.visor.pagina(ref,1);Files.writeString(page.path(),"alterada");assertEquals(409,assertThrows(FalloTecnico.class,()->x.visor.pagina(ref,1)).status);Files.writeString(x.gestion.verificarArchivo(ref),"alterado");assertEquals(409,assertThrows(FalloTecnico.class,()->x.gestion.verificarArchivo(ref)).status);}
 @Test void casoCerradoPermiteLecturaYReintentoPeroNoDocumentoNuevo(){var key=UUID.randomUUID();var doc=cargar(key);var head=x.d.catalog.operador("demo.jefatura.upr.a");var c=x.d.core.caso(head,x.uno);x.d.core.clasificar(head,UUID.randomUUID(),x.uno,new Clasificacion(c.revision(),"BAJA","Fundamento sintético"));c=x.d.core.caso(prof(),x.uno);x.d.core.revisarCaso(prof(),UUID.randomUUID(),x.uno,new Decision(c.revision(),"Cierre sintético"),"CIERRE");assertEquals(doc,cargar(key));assertEquals(409,assertThrows(FalloTecnico.class,()->cargar(UUID.randomUUID())).status);}
 @Test void indisponibilidadDeVistaNoSeAnunciaComoPrevisualizacionCompleta(){var doc=cargar(UUID.randomUUID());x.noDisponible=true;var ref=x.gestion.referencia(prof(),x.uno,doc.id());assertEquals(503,assertThrows(FalloTecnico.class,()->x.visor.vista(ref)).status);assertEquals(0,count("document_representation"));x.noDisponible=false;assertEquals("PAGINAS",x.visor.vista(ref).representacion());}
}